 let full=tag==want && if tag==1{matches!(r,Err(ProgramError::AccountAlreadyInitialized))}else{r.is_ok()};
 assert!(full != cfg!(NFQ_invert));
 kani::cover!(tag==0);kani::cover!(tag==1);kani::cover!(tag==2);
}
