pub fn qm31_m31_dot4_prepared_limbs49_bytes(
    weight_limbs: &[[u32; 4]; 49],
    bytes: &[u8],
) -> Option<[QM31; 4]> {
    if bytes.len() != 4 * 49 * 4 {
        return None;
    }

